# Fix the edge case
from collections import defaultdict

impurities = []
for r in range(height):
    for c in range(width):
        if grid[r][c] == 3:
            continue

        neighbor_counts = defaultdict(int)

        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < height and 0 <= nc < width:
                v = grid[nr][nc]
                if v != 3:
                    neighbor_counts[v] += 1

        if not neighbor_counts:
            continue

        total_neighbors = sum(neighbor_counts.values())
        max_count = max(neighbor_counts.values())

        # If less than half of neighbors match current cell's value, it's likely an impurity
        if max_count < total_neighbors * 0.4:
            impurities.append((r, c, grid[r][c], dict(neighbor_counts)))

print("Potential impurities:")
for imp in sorted(impurities):
    print(f"  ({imp[0]}, {imp[1]}): value={imp[2]}, neighbors={imp[3]}")

# Let me create a simplified theory: 
# 1. Find rectangular blocks of same color
# 2. Replace any pixel within the rectangle that differs from the block's color

grid = [
    [3, 3, 3, 3, 3, 0, 3, 3, 3, 3, 3, 3, 3, 3, 3],
    [3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3],
    [2, 2, 2, 2, 2, 2, 3, 3, 3, 7, 7, 7, 7, 7, 7],
    [2, 2, 2, 2, 2, 2, 3, 3, 3, 7, 7, 7, 7, 4, 7],
    [0, 3, 3, 3, 3, 3, 3, 3, 0, 7, 7, 7, 7, 7, 7],
    [3, 3, 3, 6, 3, 3, 3, 3, 3, 7, 7, 7, 7, 7, 7],
    [3, 3, 3, 3, 3, 3, 3, 3, 3, 7, 7, 7, 7, 7, 7],
    [3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 4, 3, 3, 3, 3],
    [3, 3, 3, 3, 3, 3, overlapping regions
]

height, width = 27, 15

# Look for visually distinct rectangular regions
# A region is defined as a maximal rectangle where most cells share the same non-3 value

def find_regions():
    """Find rectangular regions"""
    visited = [[False]*width for _ in range(height)]
    regions = []

    for r in range(height):
        for c in range(width):
            if visited[r][c] or grid[r][c] == 3:
                continue

            val = grid[r][c]

            # Expand right
            c_right = c
            while c_right + 1 < width and grid[r][c_right+1] == val:
                c_right += 1

            # Expand down
            r_bottom = r
            while r_bottom + 1 < height:
                match = True
                for cc in range(c, c_right+1):
                    if grid[r_bottom+1][cc] != val:
                        match = False
                        break
                if not match:
                    break
                r_bottom += 1

            # This defines a candidate rectangular region
            # Check how uniform it is
            cell_count = (r_bottom - r + 1) * (c_right - c + 1)
            uniform = sum(1 for rr in range(r, r_bottom+1) 
                         for cc in range(c, c_right+1) 
                         if grid[rr][cc] == val)

            # If mostly uniform (more than 80%), mark as region
            if uniform > cell_count * 0.8:
                for rr in range(r, r_bottom+1):
                    for cc in range(c, c_right+1):
                        visited[rr][cc] = True

                regions.append({
                    'val': val, 'top': r, 'bottom': r_bottom, 
                    'left': c, 'right': c_right,
                    'uniform_cells': uniform
                })

    return regions

regions = find_regions()
print(f"Found {len(regions)} regions:")
for reg in sorted(regions, key=lambda x: (-x['uniform_cells'], x['top'], x['left']))[:10]:
    print(f"  Color {reg['val']}: rows {reg['top']}-{reg['bottom']}, cols {reg['left']}-{reg['right']}, size {(reg['bottom']-reg['top']+1)*(reg['right']-reg['left']+1)}, uniform {reg['uniform_cells']}")

# Now count impurities in each region
print("\nImpurities (non-val cells in each region):")
for reg in regions:
    impurity_cells = [(r,c) for r in range(reg['top'], reg['bottom']+1) 
                      for c in range(reg['left'], reg['right']+1)
                      if grid[r][c] != reg['val']]
    if impurity_cells:
        print(f"  Region color {reg['val']}: {len(impurity_cells)} impurities at {impurity_cells}")

