G = grid  # Just use the original

def find_rect(r, c):
    """Find maximal rectangle starting at (r,c) containing non-3 cells only"""
    val = G[r][c]

    left, right = c, c
    while right + 1 < width and G[r][right+1] != 3:
        right += 1

    top, bottom = r, r
    for rr in range(r+1, height):
        full_row = True
        for cc in range(left, right+1):
            if G[rr][cc] == 3:
                full_row = False
                break
        if not full_row:
            break
        bottom += 1

    return left, top, right, bottom

def count_in_rect(rect, val):
    r1, c1, r2, c2 = rect
    cnt = 0
    for r in range(r1, r2+1):
        for c in range(c1, c2+1):
            if G[r][c] == val:
                cnt += 1
    return cnt

def get_majority(rect):
